export type HubCopy={eyebrow:string;h1a:string;h1b:string;lead:string;notice:string;details:string;logoAlt:string;syncKicker:string;syncTitle:string;syncLead:string;stepsTitle:string;revoke:string;manualKicker:string;manualTitle:string;manualLead:string;platformsKicker:string;platformsTitle:string;android:string;available:string;win:string;mac:string;linux:string;download:string;orLocal:string;ios:string;unavailable:string;platformsNote:string};
export const hubCopy:Dict<HubCopy>={
 en:{eyebrow:'APPS · ANDROID AND COMPUTER',h1a:'Your YouTube transcripts,',h1b:'from your own device',lead:'YouTube blocks cloud servers with its anti-bot check, which is why the remote MCP server cannot fetch transcripts itself. The CamMicGo app makes the request from your phone or computer, over your own connection, and gets the timestamped transcript.',notice:'Test version · debug-signed APK. Android may ask you to allow installs from your browser.',details:'Details and installation',logoAlt:'CamMicGo SEO MCP app icon',syncKicker:'SYNC WITH YOUR AI ASSISTANT',syncTitle:'How the transcript reaches your assistant',syncLead:'The remote MCP server cannot reach YouTube itself. It hands the request to your paired device, which handles it over your connection and sends the result back.',stepsTitle:'Get started in 4 steps',revoke:'You can unpair a device at any time in the app (“Dissocier”) or ask your assistant to revoke it (tool `device_revoke`). The app only receives YouTube video IDs, never commands.',manualKicker:'WITHOUT AN AI ASSISTANT',manualTitle:'Use the app on its own',manualLead:'Share a video from the YouTube app to “CamMicGo SEO MCP”, or paste its link. The transcript appears with `[mm:ss]` timestamps: copy it, export it (SRT, VTT, TXT, JSON) or share it. The original language is selected by default, and the list of the video’s other available languages lets you pick another one.',platformsKicker:'ALL DEVICES',platformsTitle:'Choose your device',android:'Phones and tablets · Android 8+',available:'Available (test)',win:'Computer app for the remote MCP · Windows 10 / 11',mac:'Computer app for the remote MCP · Apple Silicon and Intel',linux:'Computer app for the remote MCP · x64 and ARM64',download:'Download',orLocal:'or local MCP server ↗',ios:'iPhone and iPad',unavailable:'Not available yet',platformsNote:'On a computer you have two options: the computer app relays transcripts for the remote MCP server (Claude, ChatGPT), like the phone; the local MCP server fetches transcripts itself for Claude Desktop, Cursor or Gemini CLI, with no relay.'},
 fr:{eyebrow:'APPLICATIONS · ANDROID ET ORDINATEUR',h1a:'Vos transcriptions YouTube,',h1b:'depuis votre appareil',lead:'YouTube bloque les serveurs cloud avec sa vérification anti-robot : c’est pour cela que le serveur MCP distant ne peut pas récupérer les transcriptions lui-même. L’application CamMicGo fait la requête depuis votre téléphone ou votre ordinateur, avec votre propre connexion, et obtient la transcription horodatée.',notice:'Version de test · APK signé en mode debug. Android peut vous demander d’autoriser l’installation depuis votre navigateur.',details:'Détails et installation',logoAlt:'Icône de l’application CamMicGo SEO MCP',syncKicker:'SYNCHRONISATION AVEC VOTRE ASSISTANT IA',syncTitle:'Comment la transcription arrive jusqu’à votre assistant',syncLead:'Le serveur MCP distant ne peut pas joindre YouTube lui-même. Il confie la demande à votre appareil appairé, qui la traite avec votre connexion et renvoie le résultat.',stepsTitle:'Mise en route en 4 étapes',revoke:'Vous pouvez dissocier un appareil à tout moment dans l’application (« Dissocier ») ou demander à votre assistant de le révoquer (outil `device_revoke`). L’application ne reçoit que des identifiants de vidéos YouTube, jamais de commandes.',manualKicker:'SANS ASSISTANT IA',manualTitle:'Utilisation directe dans l’application',manualLead:'Partagez une vidéo depuis l’app YouTube vers « CamMicGo SEO MCP », ou collez son lien. La transcription s’affiche avec des horodatages `[mm:ss]` : copiez-la, exportez-la (SRT, VTT, TXT, JSON) ou partagez-la. La langue originale est choisie par défaut, et la liste des autres langues disponibles pour la vidéo vous permet d’en choisir une autre.',platformsKicker:'TOUS LES APPAREILS',platformsTitle:'Choisissez votre appareil',android:'Téléphones et tablettes · Android 8+',available:'Disponible (test)',win:'Application ordinateur pour le MCP distant · Windows 10 / 11',mac:'Application ordinateur pour le MCP distant · Apple Silicon et Intel',linux:'Application ordinateur pour le MCP distant · x64 et ARM64',download:'Télécharger',orLocal:'ou serveur MCP local ↗',ios:'iPhone et iPad',unavailable:'Pas encore disponible',platformsNote:'Sur ordinateur, deux options : l’application ordinateur sert de relais au serveur MCP distant (Claude, ChatGPT), comme le téléphone ; le serveur MCP local récupère lui-même les transcriptions pour Claude Desktop, Cursor ou Gemini CLI, sans relais.'},
 es:{eyebrow:'APPS · ANDROID Y ORDENADOR',h1a:'Tus transcripciones de YouTube,',h1b:'desde tu propio dispositivo',lead:'YouTube bloquea los servidores en la nube con su verificación antibots: por eso el servidor MCP remoto no puede obtener las transcripciones por sí mismo. La app CamMicGo hace la solicitud desde tu teléfono u ordenador, con tu propia conexión, y obtiene la transcripción con marcas de tiempo.',notice:'Versión de prueba · APK firmado en modo debug. Android puede pedirte que permitas instalar desde el navegador.',details:'Detalles e instalación',logoAlt:'Icono de la app CamMicGo SEO MCP',syncKicker:'SINCRONIZACIÓN CON TU ASISTENTE DE IA',syncTitle:'Cómo llega la transcripción a tu asistente',syncLead:'El servidor MCP remoto no puede acceder a YouTube. Confía la solicitud a tu dispositivo emparejado, que la procesa con tu conexión y devuelve el resultado.',stepsTitle:'Empieza en 4 pasos',revoke:'Puedes desemparejar un dispositivo en cualquier momento desde la app («Dissocier») o pedir a tu asistente que lo revoque (herramienta `device_revoke`). La app solo recibe identificadores de vídeos de YouTube, nunca órdenes.',manualKicker:'SIN ASISTENTE DE IA',manualTitle:'Uso directo en la app',manualLead:'Comparte un vídeo desde la app de YouTube a «CamMicGo SEO MCP» o pega su enlace. La transcripción aparece con marcas `[mm:ss]`: cópiala, expórtala (SRT, VTT, TXT, JSON) o compártela. El idioma original se elige por defecto y la lista de idiomas disponibles del vídeo te permite elegir otro.',platformsKicker:'TODOS LOS DISPOSITIVOS',platformsTitle:'Elige tu dispositivo',android:'Teléfonos y tabletas · Android 8+',available:'Disponible (prueba)',win:'App de ordenador para el MCP remoto · Windows 10 / 11',mac:'App de ordenador para el MCP remoto · Apple Silicon e Intel',linux:'App de ordenador para el MCP remoto · x64 y ARM64',download:'Descargar',orLocal:'o servidor MCP local ↗',ios:'iPhone y iPad',unavailable:'Aún no disponible',platformsNote:'En ordenador tienes dos opciones: la app de ordenador hace de relé para el servidor MCP remoto (Claude, ChatGPT), como el teléfono; el servidor MCP local obtiene las transcripciones por sí mismo para Claude Desktop, Cursor o Gemini CLI, sin relé.'},
 de:{eyebrow:'APPS · ANDROID UND COMPUTER',h1a:'Ihre YouTube-Transkripte,',h1b:'von Ihrem eigenen Gerät',lead:'YouTube blockiert Cloud-Server mit seiner Bot-Prüfung, deshalb kann der Remote-MCP-Server Transkripte nicht selbst abrufen. Die CamMicGo-App stellt die Anfrage von Ihrem Telefon oder Computer über Ihre eigene Verbindung und erhält das Transkript mit Zeitstempeln.',notice:'Testversion · Debug-signierte APK. Android fragt eventuell, ob Installationen aus dem Browser erlaubt werden sollen.',details:'Details und Installation',logoAlt:'App-Symbol von CamMicGo SEO MCP',syncKicker:'SYNCHRONISIERUNG MIT IHREM KI-ASSISTENTEN',syncTitle:'So gelangt das Transkript zu Ihrem Assistenten',syncLead:'Der Remote-MCP-Server erreicht YouTube nicht selbst. Er übergibt die Anfrage an Ihr gekoppeltes Gerät, das sie über Ihre Verbindung bearbeitet und das Ergebnis zurücksendet.',stepsTitle:'In 4 Schritten starten',revoke:'Sie können ein Gerät jederzeit in der App entkoppeln („Dissocier“) oder es von Ihrem Assistenten widerrufen lassen (Tool `device_revoke`). Die App erhält nur YouTube-Video-IDs, niemals Befehle.',manualKicker:'OHNE KI-ASSISTENT',manualTitle:'Direkt in der App nutzen',manualLead:'Teilen Sie ein Video aus der YouTube-App mit „CamMicGo SEO MCP“ oder fügen Sie den Link ein. Das Transkript erscheint mit `[mm:ss]`-Zeitstempeln: kopieren, exportieren (SRT, VTT, TXT, JSON) oder teilen. Standardmäßig ist die Originalsprache gewählt; die Liste der verfügbaren Sprachen des Videos erlaubt eine andere Auswahl.',platformsKicker:'ALLE GERÄTE',platformsTitle:'Wählen Sie Ihr Gerät',android:'Telefone und Tablets · Android 8+',available:'Verfügbar (Test)',win:'Computer-App für den Remote-MCP · Windows 10 / 11',mac:'Computer-App für den Remote-MCP · Apple Silicon und Intel',linux:'Computer-App für den Remote-MCP · x64 und ARM64',download:'Herunterladen',orLocal:'oder lokaler MCP-Server ↗',ios:'iPhone und iPad',unavailable:'Noch nicht verfügbar',platformsNote:'Am Computer gibt es zwei Optionen: Die Computer-App leitet Transkripte für den Remote-MCP-Server (Claude, ChatGPT) weiter, wie das Telefon; der lokale MCP-Server ruft Transkripte für Claude Desktop, Cursor oder Gemini CLI selbst ab, ohne Relay.'},
 pt:{eyebrow:'APPS · ANDROID E COMPUTADOR',h1a:'Suas transcrições do YouTube,',h1b:'do seu próprio dispositivo',lead:'O YouTube bloqueia servidores na nuvem com sua verificação anti-robô: por isso o servidor MCP remoto não consegue obter as transcrições sozinho. O app CamMicGo faz o pedido do seu telefone ou computador, com a sua própria conexão, e obtém a transcrição com marcações de tempo.',notice:'Versão de teste · APK assinado em modo debug. O Android pode pedir para permitir instalações pelo navegador.',details:'Detalhes e instalação',logoAlt:'Ícone do app CamMicGo SEO MCP',syncKicker:'SINCRONIZAÇÃO COM SEU ASSISTENTE DE IA',syncTitle:'Como a transcrição chega ao seu assistente',syncLead:'O servidor MCP remoto não consegue acessar o YouTube. Ele entrega o pedido ao seu dispositivo pareado, que o processa com a sua conexão e devolve o resultado.',stepsTitle:'Comece em 4 passos',revoke:'Você pode desparear um dispositivo a qualquer momento no app («Dissocier») ou pedir ao assistente que o revogue (ferramenta `device_revoke`). O app só recebe IDs de vídeos do YouTube, nunca comandos.',manualKicker:'SEM ASSISTENTE DE IA',manualTitle:'Uso direto no app',manualLead:'Compartilhe um vídeo do app YouTube com «CamMicGo SEO MCP» ou cole o link. A transcrição aparece com marcações `[mm:ss]`: copie, exporte (SRT, VTT, TXT, JSON) ou compartilhe. O idioma original é escolhido por padrão, e a lista de idiomas disponíveis do vídeo permite escolher outro.',platformsKicker:'TODOS OS DISPOSITIVOS',platformsTitle:'Escolha seu dispositivo',android:'Telefones e tablets · Android 8+',available:'Disponível (teste)',win:'App de computador para o MCP remoto · Windows 10 / 11',mac:'App de computador para o MCP remoto · Apple Silicon e Intel',linux:'App de computador para o MCP remoto · x64 e ARM64',download:'Baixar',orLocal:'ou servidor MCP local ↗',ios:'iPhone e iPad',unavailable:'Ainda não disponível',platformsNote:'No computador há duas opções: o app de computador faz o papel de relé para o servidor MCP remoto (Claude, ChatGPT), como o telefone; o servidor MCP local obtém as transcrições sozinho para Claude Desktop, Cursor ou Gemini CLI, sem relé.'},
 it:{eyebrow:'APP · ANDROID E COMPUTER',h1a:'Le tue trascrizioni YouTube,',h1b:'dal tuo dispositivo',lead:'YouTube blocca i server cloud con la sua verifica anti-bot: per questo il server MCP remoto non può recuperare le trascrizioni da solo. L’app CamMicGo fa la richiesta dal tuo telefono o computer, con la tua connessione, e ottiene la trascrizione con i timestamp.',notice:'Versione di prova · APK firmato in modalità debug. Android può chiederti di consentire l’installazione dal browser.',details:'Dettagli e installazione',logoAlt:'Icona dell’app CamMicGo SEO MCP',syncKicker:'SINCRONIZZAZIONE CON IL TUO ASSISTENTE IA',syncTitle:'Come la trascrizione arriva al tuo assistente',syncLead:'Il server MCP remoto non può raggiungere YouTube. Affida la richiesta al tuo dispositivo abbinato, che la elabora con la tua connessione e restituisce il risultato.',stepsTitle:'Inizia in 4 passaggi',revoke:'Puoi dissociare un dispositivo in qualsiasi momento dall’app («Dissocier») o chiedere all’assistente di revocarlo (strumento `device_revoke`). L’app riceve solo ID di video YouTube, mai comandi.',manualKicker:'SENZA ASSISTENTE IA',manualTitle:'Uso diretto nell’app',manualLead:'Condividi un video dall’app YouTube con «CamMicGo SEO MCP» oppure incolla il link. La trascrizione appare con timestamp `[mm:ss]`: copiala, esportala (SRT, VTT, TXT, JSON) o condividila. La lingua originale è scelta per impostazione predefinita e l’elenco delle lingue disponibili del video ti permette di sceglierne un’altra.',platformsKicker:'TUTTI I DISPOSITIVI',platformsTitle:'Scegli il tuo dispositivo',android:'Telefoni e tablet · Android 8+',available:'Disponibile (test)',win:'App per computer per l’MCP remoto · Windows 10 / 11',mac:'App per computer per l’MCP remoto · Apple Silicon e Intel',linux:'App per computer per l’MCP remoto · x64 e ARM64',download:'Scarica',orLocal:'oppure server MCP locale ↗',ios:'iPhone e iPad',unavailable:'Non ancora disponibile',platformsNote:'Sul computer hai due opzioni: l’app per computer fa da relè per il server MCP remoto (Claude, ChatGPT), come il telefono; il server MCP locale recupera da solo le trascrizioni per Claude Desktop, Cursor o Gemini CLI, senza relè.'},
 ru:{eyebrow:'ПРИЛОЖЕНИЯ · ANDROID И КОМПЬЮТЕР',h1a:'Расшифровки YouTube —',h1b:'с вашего устройства',lead:'YouTube блокирует облачные серверы антибот-проверкой, поэтому удалённый MCP-сервер не может сам получать расшифровки. Приложение CamMicGo делает запрос с вашего телефона или компьютера через ваше соединение и получает расшифровку с таймкодами.',notice:'Тестовая версия · APK с отладочной подписью. Android может попросить разрешить установку из браузера.',details:'Подробности и установка',logoAlt:'Значок приложения CamMicGo SEO MCP',syncKicker:'СИНХРОНИЗАЦИЯ С ИИ-АССИСТЕНТОМ',syncTitle:'Как расшифровка попадает к ассистенту',syncLead:'Удалённый MCP-сервер не может обратиться к YouTube. Он передаёт запрос сопряжённому устройству, которое выполняет его через ваше соединение и возвращает результат.',stepsTitle:'Начало работы за 4 шага',revoke:'Устройство можно отвязать в любой момент в приложении («Dissocier») или попросить ассистента отозвать его (инструмент `device_revoke`). Приложение получает только идентификаторы видео YouTube, никогда — команды.',manualKicker:'БЕЗ ИИ-АССИСТЕНТА',manualTitle:'Работа прямо в приложении',manualLead:'Поделитесь видео из приложения YouTube с «CamMicGo SEO MCP» или вставьте ссылку. Расшифровка появится с таймкодами `[mm:ss]`: скопируйте, экспортируйте (SRT, VTT, TXT, JSON) или отправьте её. По умолчанию выбран язык оригинала, а список доступных языков видео позволяет выбрать другой.',platformsKicker:'ВСЕ УСТРОЙСТВА',platformsTitle:'Выберите устройство',android:'Телефоны и планшеты · Android 8+',available:'Доступно (тест)',win:'Приложение для удалённого MCP · Windows 10 / 11',mac:'Приложение для удалённого MCP · Apple Silicon и Intel',linux:'Приложение для удалённого MCP · x64 и ARM64',download:'Скачать',orLocal:'или локальный MCP-сервер ↗',ios:'iPhone и iPad',unavailable:'Пока недоступно',platformsNote:'На компьютере есть два варианта: приложение для компьютера служит ретранслятором для удалённого MCP-сервера (Claude, ChatGPT), как телефон; локальный MCP-сервер сам получает расшифровки для Claude Desktop, Cursor или Gemini CLI, без ретранслятора.'},
 zh:{eyebrow:'应用 · ANDROID 与电脑',h1a:'你的 YouTube 字幕，',h1b:'由你自己的设备获取',lead:'YouTube 会用反机器人验证屏蔽云服务器，因此远程 MCP 服务器无法自己获取字幕。CamMicGo 应用通过你的手机或电脑、用你自己的网络发出请求，获取带时间戳的字幕。',notice:'测试版 · 调试签名的 APK。Android 可能会要求你允许从浏览器安装。',details:'详情与安装',logoAlt:'CamMicGo SEO MCP 应用图标',syncKicker:'与 AI 助手同步',syncTitle:'字幕如何到达你的助手',syncLead:'远程 MCP 服务器无法直接访问 YouTube。它把请求交给已配对的设备，设备用你的网络处理后返回结果。',stepsTitle:'4 步快速上手',revoke:'你可以随时在应用中解除配对（“Dissocier”），或让助手撤销该设备（工具 `device_revoke`）。应用只接收 YouTube 视频 ID，从不接收命令。',manualKicker:'无需 AI 助手',manualTitle:'直接在应用中使用',manualLead:'从 YouTube 应用把视频分享到“CamMicGo SEO MCP”，或粘贴链接。字幕带 `[mm:ss]` 时间戳显示：可复制、导出（SRT、VTT、TXT、JSON）或分享。默认选择原始语言，并可从视频的可用语言列表中选择其他语言。',platformsKicker:'所有设备',platformsTitle:'选择你的设备',android:'手机和平板 · Android 8+',available:'可用（测试）',win:'用于远程 MCP 的电脑应用 · Windows 10 / 11',mac:'用于远程 MCP 的电脑应用 · Apple 芯片和 Intel',linux:'用于远程 MCP 的电脑应用 · x64 和 ARM64',download:'下载',orLocal:'或本地 MCP 服务器 ↗',ios:'iPhone 和 iPad',unavailable:'暂不可用',platformsNote:'在电脑上有两种方式：电脑应用像手机一样为远程 MCP 服务器（Claude、ChatGPT）中转字幕；本地 MCP 服务器则为 Claude Desktop、Cursor 或 Gemini CLI 自行获取字幕，无需中转。'},
 ja:{eyebrow:'アプリ · ANDROID とパソコン',h1a:'YouTube の文字起こしを、',h1b:'あなたのデバイスから',lead:'YouTube はボット対策でクラウドサーバーをブロックするため、リモート MCP サーバーは自分で文字起こしを取得できません。CamMicGo アプリがスマホやパソコンからあなたの回線でリクエストし、タイムスタンプ付きの文字起こしを取得します。',notice:'テスト版 · デバッグ署名の APK。ブラウザーからのインストール許可を求められる場合があります。',details:'詳細とインストール',logoAlt:'CamMicGo SEO MCP アプリのアイコン',syncKicker:'AI アシスタントとの同期',syncTitle:'文字起こしがアシスタントに届くまで',syncLead:'リモート MCP サーバーは YouTube に直接アクセスできません。ペアリングしたデバイスにリクエストを渡し、デバイスがあなたの回線で処理して結果を返します。',stepsTitle:'4 ステップで開始',revoke:'デバイスはアプリ（「Dissocier」）からいつでも解除でき、アシスタントに取り消しを頼むこともできます（ツール `device_revoke`）。アプリが受け取るのは YouTube の動画 ID だけで、コマンドは受け取りません。',manualKicker:'AI アシスタントなしで',manualTitle:'アプリ単体で使う',manualLead:'YouTube アプリから「CamMicGo SEO MCP」に動画を共有するか、リンクを貼り付けます。文字起こしは `[mm:ss]` 付きで表示され、コピー・書き出し（SRT、VTT、TXT、JSON）・共有ができます。既定は元の言語で、動画で利用できる他の言語も一覧から選べます。',platformsKicker:'すべてのデバイス',platformsTitle:'デバイスを選択',android:'スマホとタブレット · Android 8 以降',available:'利用可能（テスト）',win:'リモート MCP 用パソコンアプリ · Windows 10 / 11',mac:'リモート MCP 用パソコンアプリ · Apple シリコンと Intel',linux:'リモート MCP 用パソコンアプリ · x64 と ARM64',download:'ダウンロード',orLocal:'またはローカル MCP サーバー ↗',ios:'iPhone と iPad',unavailable:'未提供',platformsNote:'パソコンでは 2 つの方法があります。パソコンアプリはスマホと同様にリモート MCP サーバー（Claude、ChatGPT）向けに文字起こしを中継します。ローカル MCP サーバーは Claude Desktop、Cursor、Gemini CLI 向けに自分で取得し、中継は不要です。'},
 ko:{eyebrow:'앱 · ANDROID 및 컴퓨터',h1a:'YouTube 자막을',h1b:'내 기기에서 직접',lead:'YouTube는 봇 차단 검사로 클라우드 서버를 막기 때문에 원격 MCP 서버는 자막을 직접 가져올 수 없습니다. CamMicGo 앱이 내 휴대폰이나 컴퓨터에서 내 인터넷으로 요청해 타임스탬프 자막을 가져옵니다.',notice:'테스트 버전 · 디버그 서명 APK. Android가 브라우저 설치 허용을 요청할 수 있습니다.',details:'자세한 내용 및 설치',logoAlt:'CamMicGo SEO MCP 앱 아이콘',syncKicker:'AI 어시스턴트와 동기화',syncTitle:'자막이 어시스턴트에 도착하는 방법',syncLead:'원격 MCP 서버는 YouTube에 직접 접근할 수 없습니다. 페어링된 기기에 요청을 넘기면 기기가 내 인터넷으로 처리해 결과를 돌려줍니다.',stepsTitle:'4단계로 시작하기',revoke:'앱에서 언제든 기기 연결을 해제(“Dissocier”)하거나 어시스턴트에게 취소를 요청할 수 있습니다(도구 `device_revoke`). 앱은 YouTube 동영상 ID만 받으며 명령은 받지 않습니다.',manualKicker:'AI 어시스턴트 없이',manualTitle:'앱에서 바로 사용',manualLead:'YouTube 앱에서 “CamMicGo SEO MCP”로 동영상을 공유하거나 링크를 붙여 넣으세요. 자막이 `[mm:ss]` 타임스탬프와 함께 표시되며 복사, 내보내기(SRT, VTT, TXT, JSON), 공유가 가능합니다. 기본값은 원본 언어이며 동영상에서 제공하는 다른 언어를 목록에서 고를 수 있습니다.',platformsKicker:'모든 기기',platformsTitle:'기기를 선택하세요',android:'휴대폰 및 태블릿 · Android 8+',available:'사용 가능(테스트)',win:'원격 MCP용 컴퓨터 앱 · Windows 10 / 11',mac:'원격 MCP용 컴퓨터 앱 · Apple 실리콘 및 Intel',linux:'원격 MCP용 컴퓨터 앱 · x64 및 ARM64',download:'다운로드',orLocal:'또는 로컬 MCP 서버 ↗',ios:'iPhone 및 iPad',unavailable:'아직 제공되지 않음',platformsNote:'컴퓨터에서는 두 가지 방법이 있습니다. 컴퓨터 앱은 휴대폰처럼 원격 MCP 서버(Claude, ChatGPT)를 위해 자막을 중계하고, 로컬 MCP 서버는 Claude Desktop, Cursor, Gemini CLI용 자막을 중계 없이 직접 가져옵니다.'},
 ar:{eyebrow:'التطبيقات · ANDROID والحاسوب',h1a:'تفريغات YouTube الخاصة بك،',h1b:'من جهازك أنت',lead:'يحظر YouTube الخوادم السحابية عبر التحقق من الروبوتات، لذلك لا يستطيع خادم MCP البعيد جلب التفريغات بنفسه. يرسل تطبيق CamMicGo الطلب من هاتفك أو حاسوبك عبر اتصالك الخاص ويحصل على النص المؤقَّت.',notice:'نسخة تجريبية · ملف APK موقّع بوضع التصحيح. قد يطلب Android السماح بالتثبيت من المتصفح.',details:'التفاصيل والتثبيت',logoAlt:'أيقونة تطبيق CamMicGo SEO MCP',syncKicker:'المزامنة مع مساعدك الذكي',syncTitle:'كيف يصل التفريغ إلى مساعدك',syncLead:'لا يستطيع خادم MCP البعيد الوصول إلى YouTube. فيسلّم الطلب إلى جهازك المقترن الذي يعالجه عبر اتصالك ويعيد النتيجة.',stepsTitle:'ابدأ في 4 خطوات',revoke:'يمكنك فك اقتران أي جهاز في أي وقت من التطبيق («Dissocier») أو أن تطلب من مساعدك إلغاءه (أداة `device_revoke`). لا يتلقى التطبيق إلا معرّفات فيديوهات YouTube، ولا أوامر أبدًا.',manualKicker:'بدون مساعد ذكي',manualTitle:'الاستخدام المباشر في التطبيق',manualLead:'شارك فيديو من تطبيق YouTube إلى «CamMicGo SEO MCP» أو الصق رابطه. يظهر التفريغ مع توقيتات `[mm:ss]`: انسخه أو صدّره (SRT وVTT وTXT وJSON) أو شاركه. تُختار اللغة الأصلية افتراضيًا، وتتيح لك قائمة اللغات المتاحة للفيديو اختيار لغة أخرى.',platformsKicker:'جميع الأجهزة',platformsTitle:'اختر جهازك',android:'الهواتف والأجهزة اللوحية · Android 8+',available:'متاح (تجريبي)',win:'تطبيق الحاسوب لخادم MCP البعيد · Windows 10 / 11',mac:'تطبيق الحاسوب لخادم MCP البعيد · Apple Silicon وIntel',linux:'تطبيق الحاسوب لخادم MCP البعيد · x64 وARM64',download:'تنزيل',orLocal:'أو خادم MCP المحلي ↗',ios:'iPhone وiPad',unavailable:'غير متاح بعد',platformsNote:'على الحاسوب خياران: تطبيق الحاسوب يعمل وسيطًا لخادم MCP البعيد (Claude وChatGPT) مثل الهاتف، أما خادم MCP المحلي فيجلب التفريغات بنفسه لـ Claude Desktop وCursor وGemini CLI دون وسيط.'},
};

